Here is the commit message:
netdev: fix double-free in netdev_nl_bind_rx_doit()

Sashiko flags that genlmsg_reply() always consumes the skb.
The error path calls nlmsg_free(rsp) so we can't jump directly
to it. Let's not unbind, just propagate the error to the user.
This is the typical way of handling genlmsg_reply() failures.
They shouldn't happen unless user does something silly like
calling the kernel with an already-full rcvbuf.

Reported-by: Sashiko <sashiko-bot@kernel.org>
Fixes: 170aafe35cb9 ("netdev: support binding dma-buf to netdevice")
Reviewed-by: Bobby Eshleman <bobbyeshleman@meta.com>
Acked-by: Daniel Borkmann <daniel@iogearbox.net>
Reviewed-by: Nikolay Aleksandrov <razor@blackwall.org>
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
genlmsg_reply() always consumes the skb regardless of success or failure, but the original error path (err_unbind) attempted to free the same skb again via nlmsg_free(rsp), leading to a double-free. Additionally, the error path incorrectly performed an unbind operation that should not occur after a successful bind.

Here is the patch:

 int netdev_nl_bind_rx_doit(struct sk_buff *skb, struct genl_info *info)
 {
 	struct net_devmem_dmabuf_binding *binding;
 	u32 ifindex, dmabuf_fd, rxq_idx;
 	struct netdev_nl_sock *priv;
 	struct net_device *netdev;
 	unsigned long *rxq_bitmap;
 	struct device *dma_dev;
 	struct sk_buff *rsp;
 	int err = 0;
 	void *hdr;

 	if (GENL_REQ_ATTR_CHECK(info, NETDEV_A_DEV_IFINDEX) ||
 	    GENL_REQ_ATTR_CHECK(info, NETDEV_A_DMABUF_FD) ||
 	    GENL_REQ_ATTR_CHECK(info, NETDEV_A_DMABUF_QUEUES))
 		return -EINVAL;

 	ifindex = nla_get_u32(info->attrs[NETDEV_A_DEV_IFINDEX]);
 	dmabuf_fd = nla_get_u32(info->attrs[NETDEV_A_DMABUF_FD]);

 	priv = genl_sk_priv_get(&netdev_nl_family, NETLINK_CB(skb).sk);
 	if (IS_ERR(priv))
 		return PTR_ERR(priv);

 	rsp = genlmsg_new(GENLMSG_DEFAULT_SIZE, GFP_KERNEL);
 	if (!rsp)
 		return -ENOMEM;

 	hdr = genlmsg_iput(rsp, info);
 	if (!hdr) {
 		err = -EMSGSIZE;
 		goto err_genlmsg_free;
 	}

 	mutex_lock(&priv->lock);

 	err = 0;
 	netdev = netdev_get_by_index_lock(genl_info_net(info), ifindex);
 	if (!netdev) {
 		err = -ENODEV;
 		goto err_unlock_sock;
 	}
 	if (!netif_device_present(netdev))
 		err = -ENODEV;
 	else if (!netdev_need_ops_lock(netdev))
 		err = -EOPNOTSUPP;
 	if (err) {
 		NL_SET_BAD_ATTR(info->extack,
 				info->attrs[NETDEV_A_DEV_IFINDEX]);
 		goto err_unlock;
 	}

 	rxq_bitmap = bitmap_zalloc(netdev->real_num_rx_queues, GFP_KERNEL);
 	if (!rxq_bitmap) {
 		err = -ENOMEM;
 		goto err_unlock;
 	}

 	err = netdev_nl_read_rxq_bitmap(info, netdev->real_num_rx_queues,
 					rxq_bitmap);
 	if (err)
 		goto err_rxq_bitmap;

 	dma_dev = netdev_nl_get_dma_dev(netdev, rxq_bitmap, info->extack);
 	if (IS_ERR(dma_dev)) {
 		err = PTR_ERR(dma_dev);
 		goto err_rxq_bitmap;
 	}

 	binding = net_devmem_bind_dmabuf(netdev, dma_dev, DMA_FROM_DEVICE,
 					 dmabuf_fd, priv, info->extack);
 	if (IS_ERR(binding)) {
 		err = PTR_ERR(binding);
 		goto err_rxq_bitmap;
 	}

 	for_each_set_bit(rxq_idx, rxq_bitmap, netdev->real_num_rx_queues) {
 		err = net_devmem_bind_dmabuf_to_queue(netdev, rxq_idx, binding,
 						      info->extack);
 		if (err)
 			goto err_unbind;
 	}

 	nla_put_u32(rsp, NETDEV_A_DMABUF_ID, binding->id);
 	genlmsg_end(rsp, hdr);

 	err = genlmsg_reply(rsp, info);
-	if (err)
-		goto err_unbind;

 	bitmap_free(rxq_bitmap);

 	netdev_unlock(netdev);

 	mutex_unlock(&priv->lock);

-	return 0;
+	return err < 0 ? err : 0;

 err_unbind:
 	net_devmem_unbind_dmabuf(binding);
 err_rxq_bitmap:
 	bitmap_free(rxq_bitmap);
 err_unlock:
 	netdev_unlock(netdev);
 err_unlock_sock:
 	mutex_unlock(&priv->lock);
 err_genlmsg_free:
 	nlmsg_free(rsp);
 	return err;
 }



